export function denseGlowBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const critical = clamp01(Math.max(0, input.criticalCount) / 3), crowd = clamp01(input.crowd), stress = clamp01(crowd * .78 + critical * .18 + (input.bossActive ? .04 : 0)), strongGlowLimit = stress >= .76 ? 1 : stress >= .46 ? 2 : 3, laneReserve = input.safeLaneVisible ? .02 : 0, accessibility = (reducedMotion ? .998 : 1) * (reducedFlash ? .95 : 1); return { stress, strongGlowLimit, canonicalGlowBlurScale: 1, secondaryGlowBlurScale: Math.max(.68, 1 - stress * .16 - laneReserve) * accessibility, safeLaneGlowBlurScale: 1, presentationOnly: true }; }
